"""Generate 20 Junior 2 Reading Comprehension articles (100 questions)."""
import json, re, sys

def make_art(aid, qtext, ans, analysis):
    return {"id":aid,"type":"choice","subject":"english","grade":8,
            "difficulty":"medium","question":qtext,"options":[],
            "answer":ans,"analysis":analysis}

