output_path = '/Volumes/ORICO/xinwen/claudecode/chinese-learn/src/data/questions_en_j2_reading.json'
with open(output_path, 'w', encoding='utf-8') as f:
    json.dump(A, f, ensure_ascii=False, indent=2)

print(f"\n✅ Generated {len(A)} articles ({len(A)*5} questions)")
print(f"Output: {output_path}")

# VALIDATION
from collections import Counter
ans_counter = Counter()
issues = []

for idx, art in enumerate(A):
    q = art['question']
    ans = art['answer']
    
    # Count answers
    for c in ans:
        if c in 'ABCD':
            ans_counter[c] += 1
    
    # Check options per sub-question
    for sub in range(1, 6):
        pat = rf'\({sub}\)\s+'
        parts = re.split(pat, q)
        if len(parts) < 2:
            issues.append(f"Art{idx+1} Q{sub}: missing")
            continue
        sq = parts[2] if len(parts) > 2 else parts[1]
        # Trim to before next (N)
        nm = re.search(r'\(\d+\)', sq)
        if nm:
            sq = sq[:nm.start()]
        
        opts = re.findall(r'([A-D])\.', sq)
        if len(opts) != 4:
            issues.append(f"Art{idx+1} Q{sub}: {len(opts)} opts ({opts})")
            continue
        
        olens = re.findall(r'([A-D])\.(.+?)(?:\s*[A-D]\.|$)', sq, re.DOTALL)
        lens = [(o, len(t.strip())) for o,t in olens if t.strip()]
        if len(lens) == 4:
            ls = [l[1] for l in lens]
            mn, mx = min(ls), max(ls)
            if mn > 3 and mx/mn > 1.35:
                issues.append(f"RATIO Art{idx+1} Q{sub}: {mx/mn:.2f} {lens}")

total = sum(ans_counter.values())
print(f"\n📊 Answer Distribution ({total} total):")
for c in 'ABCD':
    pct = ans_counter[c]/total*100 if total else 0
    bar = '█' * round(pct/5)
    print(f"  {c}: {ans_counter[c]:3d} ({pct:5.1f}%) {bar}")

if issues:
    print(f"\n⚠️ Issues: {len(issues)}")
    for i in issues[:10]:
        print(f"  - {i}")
else:
    print("\n✅ ALL CHECKS PASSED!")
